5174:         let cut = remaining.lastIndexOf(" ", 420);
5175:         if (cut < 180) cut = 420;
5176:         chunks.push(remaining.slice(0, cut).trim());
5177:         remaining = remaining.slice(cut).trim();
5178:       }
5179:       if (remaining) chunks.push(remaining);
5180:       const translatedChunks = await Promise.all(chunks.map(chunk => translateToPortuguese(chunk, sourceLanguage)));
5181:       return decodeNewsText(translatedChunks.join(" "));
5182:     }
5183:     const translationKey = "v3:" + sourceLanguage + ":" + value;
5184:     if (translationCache.has(translationKey)) return translationCache.get(translationKey);
5185:     if (translationInFlight.has(translationKey)) return translationInFlight.get(translationKey);
5186:     const request = (async () => {
5187:       await waitForTranslationSlot();
5188:       if (sb?.functions?.invoke) {
